const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const lakeTuz = ee.Geometry.Polygon([
      [33.0, 38.7], [33.8, 38.7], [33.8, 39.1], [33.0, 39.1], [33.0, 38.7]
    ]);

    const aug1988 = ee.DateRange('1988-08-01', '1988-08-31');
    const aug2016 = ee.DateRange('2016-08-01', '2016-08-31');

    // 2. Data Acquisition - Landsat 5 for 1988, Landsat 8 for 2016
    let col1988 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
      .filterBounds(lakeTuz)
      .filterDate(aug1988)
      .filter(ee.Filter.lt('CLOUD_COVER', 50));

    let col2016 = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
      .filterBounds(lakeTuz)
      .filterDate(aug2016)
      .filter(ee.Filter.lt('CLOUD_COVER', 50));

    // Check collection sizes
    const size1988 = col1988.size().getInfo();
    const size2016 = col2016.size().getInfo();

    print(`1988 Images: ${size1988}, 2016 Images: ${size2016}`);

    if (size1988 === 0 || size2016 === 0) {
      print("<answer>C1</answer>");
      return;
    }

    // 3. Processing - Get median composites and calculate water area
    const composite1988 = col1988.median();
    const composite2016 = col2016.median();

    // Calculate NDWI for water detection
    const ndwi1988 = composite1988.normalizedDifference(['B2', 'B4']).rename('NDWI');
    const ndwi2016 = composite2016.normalizedDifference(['B3', 'B5']).rename('NDWI');

    // Create water masks (NDWI > 0.0 indicates water)
    const water1988 = ndwi1988.gt(0.0);
    const water2016 = ndwi2016.gt(0.0);

    // Calculate water pixel counts
    const waterCount1988 = water1988.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeTuz,
      scale: 30,
      maxPixels: 1e9
    }).get('NDWI').getInfo();

    const waterCount2016 = water2016.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeTuz,
      scale: 30,
      maxPixels: 1e9
    }).get('NDWI').getInfo();

    // Convert to area in square kilometers
    const pixelArea = 0.0009; // 30m x 30m = 900 sq m = 0.0009 sq km
    const area1988 = waterCount1988 * pixelArea;
    const area2016 = waterCount2016 * pixelArea;

    print(`1988 Water Area: ${area1988.toFixed(2)} sq km`);
    print(`2016 Water Area: ${area2016.toFixed(2)} sq km`);
    print(`Change: ${(area2016 - area1988).toFixed(2)} sq km`);

    // 4. Validation & Final Answer
    if (waterCount1988 === 0 || waterCount2016 === 0) {
      print("<answer>C2</answer>");
    } else if (area1988 === null || area2016 === null || 
               !isFinite(area1988) || !isFinite(area2016)) {
      print("<answer>C3</answer>");
    } else if (area2016 < area1988) {
      print("<answer>A</answer>");
    } else {
      print("<answer>B</answer>");
    }

  } catch (error) {
    print(`Error: ${error}`);
    print("<answer>D</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
